from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
Left = Motor(Port.E, Direction.CLOCKWISE)
Right = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(Left, Right, 56, 4.375 * 25.4)
Flipper = Motor(Port.D, Direction.COUNTERCLOCKWISE)


# The main program starts here.
print('Mission', '3')
drive_base.straight(-400)
Flipper.run_angle(500, -450)
drive_base.settings(straight_speed=400)
drive_base.straight(150)
Flipper.run_angle(500, 450)
drive_base.straight(-150)
Flipper.run_angle(500, -450)
drive_base.settings(straight_speed=350)
drive_base.straight(150)
Flipper.run_angle(500, 450)
drive_base.straight(400)
